// Ready-made layout widgets generated by `-g widget <preset>`. Links are plain
// data props so projects can wire their own routes, icons and styling.
export const WIDGET_PRESETS = ["navbar", "sidebar", "footer", "bottom-bar"];

const presets = {
  navbar: {
    component: "Navbar",
    element: "header",
    navLabel: "Main navigation",
    brand: true,
    items: [
      ["Home", "/"],
      ["About", "/about"],
    ],
  },
  sidebar: {
    component: "Sidebar",
    element: "aside",
    navLabel: "Sidebar navigation",
    brand: false,
    items: [
      ["Dashboard", "/"],
      ["Settings", "/settings"],
    ],
  },
  footer: {
    component: "Footer",
    element: "footer",
    navLabel: "Footer navigation",
    brand: true,
    items: [
      ["Privacy", "/privacy"],
      ["Terms", "/terms"],
    ],
  },
  "bottom-bar": {
    component: "BottomBar",
    element: "nav",
    navLabel: "Bottom navigation",
    brand: false,
    items: [
      ["Home", "/"],
      ["Search", "/search"],
      ["Profile", "/profile"],
    ],
  },
};

export function isWidgetPreset(name) {
  return WIDGET_PRESETS.includes(name);
}

// Vue lint requires multi-word component names and reserves "footer".
export function vueWidgetPresetComponent(name) {
  return `App${presets[name].component}`;
}

function itemsLiteral(items, indent) {
  return items
    .map(([label, href]) => `${indent}{ label: "${label}", href: "${href}" },`)
    .join("\n");
}

function reactFooterYear(preset) {
  return preset.component === "Footer"
    ? "\n      <p>{`© ${new Date().getFullYear()} ${brand}`}</p>"
    : "";
}

// Mirrors Prettier/Biome: keep the destructured signature on one line when it
// fits in 80 columns.
function reactSignature(component, args) {
  const inline = `export function ${component}({ ${args.join(", ")} }: ${component}Props) {`;
  return inline.length <= 80
    ? inline
    : `export function ${component}({\n${args.map((arg) => `  ${arg},`).join("\n")}\n}: ${component}Props) {`;
}

export function reactWidgetPresetContent(name, { framework }) {
  const preset = presets[name];
  const isNext = framework === "nextjs";
  const link = isNext ? "Link" : "a";
  const linkImport = isNext ? 'import Link from "next/link";\n\n' : "";
  const tag = preset.element;
  const brandProp = preset.brand ? "\n  brand?: string;" : "";
  const args = ["items = defaultItems", ...(preset.brand ? ['brand = "App"'] : [])];
  const brandMarkup = preset.brand ? "\n      <strong>{brand}</strong>" : "";
  const navOpen = tag === "nav" ? `<nav aria-label="${preset.navLabel}">` : `<${tag}>`;
  const listIndent = tag === "nav" ? "      " : "        ";
  const list = `${listIndent}<ul>
${listIndent}  {items.map((item) => (
${listIndent}    <li key={item.href}>
${listIndent}      <${link} href={item.href}>{item.label}</${link}>
${listIndent}    </li>
${listIndent}  ))}
${listIndent}</ul>`;
  const body =
    tag === "nav"
      ? list
      : `      <nav aria-label="${preset.navLabel}">
${list}
      </nav>`;

  return `${linkImport}export type ${preset.component}Item = {
  label: string;
  href: string;
};

type ${preset.component}Props = {
  items?: ${preset.component}Item[];${brandProp}
};

const defaultItems: ${preset.component}Item[] = [
${itemsLiteral(preset.items, "  ")}
];

${reactSignature(preset.component, args)}
  return (
    ${navOpen}${brandMarkup}
${body}${reactFooterYear(preset)}
    </${tag}>
  );
}
`;
}

export function vueWidgetPresetContent(name, { framework }) {
  const preset = presets[name];
  const link = framework === "nuxt" ? "NuxtLink" : "a";
  const linkAttr = framework === "nuxt" ? ':to="item.href"' : ':href="item.href"';
  const tag = preset.element;
  const brandProp = preset.brand ? "\n  brand?: string;" : "";
  const brandDefault = preset.brand ? `\n    brand: "App",` : "";
  const brandMarkup = preset.brand ? "\n    <strong>{{ brand }}</strong>" : "";
  const navOpen = tag === "nav" ? `<nav aria-label="${preset.navLabel}">` : `<${tag}>`;
  const indent = tag === "nav" ? "    " : "      ";
  const list = `${indent}<ul>
${indent}  <li
${indent}    v-for="item in items"
${indent}    :key="item.href"
${indent}  >
${indent}    <${link} ${linkAttr}>
${indent}      {{ item.label }}
${indent}    </${link}>
${indent}  </li>
${indent}</ul>`;
  const body =
    tag === "nav"
      ? list
      : `    <nav aria-label="${preset.navLabel}">
${list}
    </nav>`;
  const year =
    preset.component === "Footer"
      ? "\n    <p>&copy; {{ new Date().getFullYear() }} {{ brand }}</p>"
      : "";

  return `<script setup lang="ts">
type ${preset.component}Item = {
  label: string;
  href: string;
};

withDefaults(
  defineProps<{
    items?: ${preset.component}Item[];${brandProp}
  }>(),
  {
    items: () => [
${itemsLiteral(preset.items, "      ")}
    ],${brandDefault}
  },
);
</script>

<template>
  ${navOpen}${brandMarkup}
${body}${year}
  </${tag}>
</template>
`;
}

// SvelteKit lint requires resolve() for internal links, and resolve() only
// accepts pathnames that exist, so defaults start with the root route.
export function svelteWidgetPresetContent(name) {
  const preset = presets[name];
  const tag = preset.element;
  const brandType = preset.brand ? "; brand?: string" : "";
  const brandArg = preset.brand ? `, brand = "App"` : "";
  const brandMarkup = preset.brand ? "\n  <strong>{brand}</strong>" : "";
  const navOpen = tag === "nav" ? `<nav aria-label="${preset.navLabel}">` : `<${tag}>`;
  const indent = tag === "nav" ? "  " : "    ";
  const list = `${indent}<ul>
${indent}  {#each items as item (item.href)}
${indent}    <li><a href={resolve(item.href)}>{item.label}</a></li>
${indent}  {/each}
${indent}</ul>`;
  const body =
    tag === "nav"
      ? list
      : `  <nav aria-label="${preset.navLabel}">
${list}
  </nav>`;
  const year =
    preset.component === "Footer"
      ? "\n  <p>&copy; {new Date().getFullYear()} {brand}</p>"
      : "";

  return `<script lang="ts">
  import { resolve } from "$app/paths";
  import type { Pathname } from "$app/types";

  type ${preset.component}Item = { label: string; href: Pathname };

  const defaultItems: ${preset.component}Item[] = [
${itemsLiteral([["Home", "/"]], "    ")}
  ];

  let { items = defaultItems${brandArg} }: { items?: ${preset.component}Item[]${brandType} } = $props();
</script>

${navOpen}${brandMarkup}
${body}${year}
</${tag}>
`;
}
